// ── Receiver ─────────────────────────────────────────────────────
class TextDocument {
  constructor(content = '') {
    this.content = content;
  }
  insert(text, pos) {
    this.content =
      this.content.slice(0, pos) + text + this.content.slice(pos);
  }
  delete(pos, len) {
    this.content =
      this.content.slice(0, pos) + this.content.slice(pos + len);
  }
  toString() { return this.content; }
}

// ── ConcreteCommands ─────────────────────────────────────────────
class InsertCommand {
  constructor(doc, text, pos) {
    this._doc = doc;
    this._text = text;
    this._pos = pos;
  }
  execute() { this._doc.insert(this._text, this._pos); }
  undo()    { this._doc.delete(this._pos, this._text.length); }
}

class DeleteCommand {
  constructor(doc, pos, len) {
    this._doc = doc;
    this._pos = pos;
    this._len = len;
    this._saved = '';   // captured on execute, not before
  }
  execute() {
    // Save BEFORE deleting — this is the critical step
    this._saved = this._doc.content.slice(this._pos, this._pos + this._len);
    this._doc.delete(this._pos, this._len);
  }
  undo() {
    this._doc.insert(this._saved, this._pos);
  }
}

// ── Invoker with undo/redo stacks ────────────────────────────────
class CommandHistory {
  constructor() {
    this._undo = [];
    this._redo = [];
  }

  run(cmd) {
    cmd.execute();
    this._undo.push(cmd);
    this._redo = [];           // fork history — clear redo
  }

  undoLast() {
    const cmd = this._undo.pop();
    if (!cmd) { console.log('Nothing to undo'); return; }
    cmd.undo();
    this._redo.push(cmd);
  }

  redoLast() {
    const cmd = this._redo.pop();
    if (!cmd) { console.log('Nothing to redo'); return; }
    cmd.execute();
    this._undo.push(cmd);
  }
}

// ── Demo ─────────────────────────────────────────────────────────
const doc     = new TextDocument('Hello World');
const history = new CommandHistory();

console.log(doc.toString());             // Hello World

history.run(new InsertCommand(doc, ', JS', 5));
console.log(doc.toString());             // Hello, JS World

history.run(new DeleteCommand(doc, 0, 6));
console.log(doc.toString());             // JS World

history.undoLast();
console.log(doc.toString());             // Hello, JS World

history.undoLast();
console.log(doc.toString());             // Hello World

history.redoLast();
console.log(doc.toString());             // Hello, JS World

// ── MacroCommand ─────────────────────────────────────────────────
class MacroCommand {
  constructor() { this._commands = []; }

  add(cmd) { this._commands.push(cmd); return this; }

  execute() {
    // Forward order
    for (const cmd of this._commands) cmd.execute();
  }

  undo() {
    // Reverse order — last action undone first
    for (let i = this._commands.length - 1; i >= 0; i--) {
      this._commands[i].undo();
    }
  }
}

// ── Serializable Command for task queues ─────────────────────────
class SendEmailCommand {
  constructor({ to, subject, body }) {
    this.type    = 'SendEmail';   // discriminator for deserialization
    this._to      = to;
    this._subject = subject;
    this._body    = body;
    this._sentId  = null;
  }

  async execute() {
    // Real implementation calls an email SDK; simplified here
    this._sentId = `msg_${Date.now()}`;
    console.log(`[Email] Sent "${this._subject}" → ${this._to}`);
  }

  async undo() {
    // Some email providers support recall within a time window
    if (this._sentId) {
      console.log(`[Email] Attempting recall of ${this._sentId}`);
    }
  }

  toJSON() {
    return { type: this.type, to: this._to, subject: this._subject, body: this._body };
  }

  static fromJSON({ to, subject, body }) {
    return new SendEmailCommand({ to, subject, body });
  }
}

// ── Simple in-process task queue (mirrors BullMQ semantics) ──────
class TaskQueue {
  constructor() { this._q = []; }

  enqueue(cmd) { this._q.push(cmd); }

  async flush() {
    while (this._q.length) {
      const cmd = this._q.shift();
      try {
        await cmd.execute();
      } catch (err) {
        console.error('Job failed, re-queuing for retry:', err);
        this._q.push(cmd);    // simplistic retry
        break;
      }
    }
  }
}

// ── Demo: macro + task queue ─────────────────────────────────────
const doc  = new TextDocument('The quick brown fox');
const hist = new CommandHistory();

// Build a macro: delete 'quick ' and insert 'slow '
const macro = new MacroCommand()
  .add(new DeleteCommand(doc, 4, 6))   // delete 'quick '
  .add(new InsertCommand(doc, 'slow ', 4));

hist.run(macro);
console.log(doc.toString()); // The slow brown fox

hist.undoLast();             // one undo reverts both operations
console.log(doc.toString()); // The quick brown fox

// Task queue
const queue = new TaskQueue();
queue.enqueue(new SendEmailCommand({ to: 'alice@example.com', subject: 'Welcome', body: 'Hi!' }));
queue.enqueue(new SendEmailCommand({ to: 'bob@example.com',   subject: 'Invoice', body: '$99' }));
queue.flush();
